### Bidirectional Control with the L293D

Let's test all four states of the L293D Channel 1 driver using Arduino digital pins 7, 8, and 9.

```cpp
// L293D Dual H-Bridge Motor Control Sketch
// Channel 1 wired to DC Motor A
const int enablePin = 9; // Pin 1 on L293D (1,2EN)
const int in1Pin    = 8; // Pin 2 on L293D (1A)
const int in2Pin    = 7; // Pin 7 on L293D (2A)

void setup() {
  pinMode(enablePin, OUTPUT);
  pinMode(in1Pin, OUTPUT);
  pinMode(in2Pin, OUTPUT);

  // Safety initial condition: motor de-energized
  stopMotor();

  Serial.begin(9600);
  Serial.println(F("--- L293D Direction Controller Ready ---"));
}

void driveForward() {
  digitalWrite(in1Pin, HIGH);
  digitalWrite(in2Pin, LOW);
  digitalWrite(enablePin, HIGH); // Enable Channel 1
  Serial.println(F("MOTOR: Forward (IN1=HIGH, IN2=LOW)"));
}

void driveReverse() {
  digitalWrite(in1Pin, LOW);
  digitalWrite(in2Pin, HIGH);
  digitalWrite(enablePin, HIGH); // Enable Channel 1
  Serial.println(F("MOTOR: Reverse (IN1=LOW, IN2=HIGH)"));
}

void brakeMotor() {
  // Active dynamic brake: short both motor terminals to HIGH
  digitalWrite(in1Pin, HIGH);
  digitalWrite(in2Pin, HIGH);
  digitalWrite(enablePin, HIGH);
  Serial.println(F("MOTOR: Dynamic Brake (IN1=HIGH, IN2=HIGH)"));
}

void stopMotor() {
  // Coast to stop: disable H-Bridge outputs
  digitalWrite(in1Pin, LOW);
  digitalWrite(in2Pin, LOW);
  digitalWrite(enablePin, LOW);
  Serial.println(F("MOTOR: Stopped / Coasting"));
}

void loop() {
  driveForward();
  delay(2000);

  brakeMotor();
  delay(1000);

  driveReverse();
  delay(2000);

  stopMotor();
  delay(1000);
}
```

### Code Breakdown:
- `pinMode()` calls configure Pins 7, 8, and 9 as outputs to drive the L293D inputs.
- `driveForward()` sets `in1Pin = HIGH` and `in2Pin = LOW`, connecting motor terminal 1 to VCC2 and terminal 2 to GND.
- `driveReverse()` swaps the logic levels (`in1Pin = LOW`, `in2Pin = HIGH`), reversing voltage polarity across the motor.
- `brakeMotor()` sets both inputs HIGH with enable active, creating a regenerative electrical brake that halts rotation quickly.
